for (const [i, card] of [...document.querySelectorAll('.themechoices > div')].entries()) { const names=['light','dark','contrast','purple','blue','yellow']; card.tabIndex=0; card.setAttribute('role','button'); card.setAttribute('aria-pressed',String(theme===names[i])); const choose=()=>{const u=new URL(location.href);u.searchParams.set('theme',names[i]);location.href=u.href};card.addEventListener('click',choose);card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}}); }
